function language(){return ['zh','en'].includes(state?.settings?.language)?state.settings.language:fallbackLanguage;}
const t=k=>(language()==='en'?en:zh)[k]||k;
function errorText(cause,prefix='requestError'){
 const message=typeof cause==='string'?cause:cause?.message||t('messageError');
 const exact=Object.keys(zh).find(key=>zh[key]===message||en[key]===message);if(exact)return t(exact);
 const named={NotAllowedError:'micPermissionDenied',PermissionDeniedError:'micPermissionDenied',NotFoundError:'micNotFound',DevicesNotFoundError:'micNotFound',NotReadableError:'micBusy',TrackStartError:'micBusy'};if(named[cause?.name])return t(named[cause.name]);
 const telegramCode=/^Telegram rejected the request \((401|409|429)\)$/.exec(message);if(telegramCode)return t({'401':'telegramTokenInvalid','409':'telegramBotBusy','429':'telegramRateLimited'}[telegramCode[1]])+' ('+telegramCode[1]+')';
 const known=[[/^Stop active work and return computer control before changing its connection$/,'vmConnectionBusy'],[/^No VM connection is configured[.]/,'vmConfigNeeded'],[/^The VM SSH (?:private key is missing or unreadable|key path is missing|key must be an existing)/,'vmKeyMissing'],[/^The VM host, user or SSH port is invalid[.]/,'vmDetailsInvalid'],[/^Several existing VM connections were found[.]/,'selectVMProfile'],[/^A valid VM connection already exists[.]/,'currentVMProtected'],[/^Invalid Telegram bot token$/,'telegramTokenInvalid'],[/^Disconnect the current Telegram owner before pairing another$/,'telegramUnpairFirst'],[/^Telegram.*(?:unauthorized|token is invalid|invalid.*token)/i,'telegramTokenInvalid'],[/^Invalid appearance preferences?(?:: [a-zA-Z]+)?$/,'appearanceInvalid'],[/^The computer connected, but its default response language could not be updated[.]$/,'responseLanguageNotUpdated'],[/^Invalid local API route$/,'invalidLocalRoute'],[/^Invalid JSON response from local service$/,'invalidServiceResponse'],[/^Local API response was interrupted$/,'responseInterrupted'],[/^Local API response is too large$/,'responseTooLarge'],[/^The local controller is disconnected$/,'connectionLost'],[/^The request outcome is unconfirmed[. ]|^The VM connection ended before the result was confirmed|^Check the unconfirmed message before sending again$/,'sendUnknownHint'],[/^The voice call changed$|^The subscription voice call changed$/,'callChanged'],[/^The (?:subscription |voice )?call is not ready$/,'callNotReady'],[/^A (?:subscription )?call is already active$/,'callAlreadyActive'],[/^Configure the optional voice API key first$/,'voiceKeyRequired'],[/^End the (?:voice )?call before resuming/,'resumeAfterCall'],[/^End the (?:voice )?call before taking control[.]?$/,'endCallBeforeControl'],[/^Desktop control session expired|^Desktop control session expired or does not match$/,'sessionExpired'],[/^The Windows speech recognition language is not installed/,'speechLanguageMissing'],[/^Windows Speech is unavailable$/,'speechUnavailable'],[/^Speech operation timed out$/,'speechTimedOut'],[/^Read-aloud text exceeds 10000 characters/,'speechTooLong'],[/^Speech cancelled$/,'speechCancelled']];
 for(const [pattern,key]of known)if(pattern.test(message))return t(key);
 const timeout=/^Timed out: (.+)$/.exec(message);if(timeout)return t('requestTimedOut')+': '+timeout[1];
 return t(prefix)+(language()==='zh'?'：':': ')+message;
}
async function changeLanguage(value){if(!['zh','en'].includes(value))return;await api('/settings',{method:'PATCH',body:{language:value}});fallbackLanguage=value;localStorage.setItem('dant.language',value);if(state)state.settings.language=value;render();}
function vmProviderLabel(provider){return provider==='hyperv'?'Hyper-V':provider==='vmware'?'VMware Workstation':provider==='auto'?t('providerAuto'):t('computerSystem');}
function reactionName(emoji){return defaultReactions.find(item=>item.emoji===emoji)?.[language()]||emoji;}
function vmConfiguredProvider(){const vm=state.settings.vm||{},setup=state.provisioning;return vm.provider||(setup?.connection?.host===vm.host?setup.provider:null);}
function vmSystemDescription(){const provider=vmConfiguredProvider();return ['hyperv','vmware'].includes(provider)?'Ubuntu · '+vmProviderLabel(provider):t('computerSystem');}
function vmProviderStatus(){const setup=state.provisioning||{};return {provider:setup.running?setup.provider:provisionDraft.provider&&provisionDraft.provider!=='auto'?provisionDraft.provider:vmProviderInfo?.provider||setup.provider,availableProviders:setup.availableProviders?.length?setup.availableProviders:vmProviderInfo?.availableProviders||[]};}
async function loadVMProviders(){if(vmProvidersBusy)return;vmProvidersBusy=true;vmProvidersError='';render();try{vmProviderInfo=await api('/vm/providers');}catch(error){vmProvidersError=error.message;}finally{vmProvidersBusy=false;render();}}
