 if(!response.ok){const body=await response.json().catch(()=>({error:response.statusText})),error=Error(body.error||t('messageError'));error.status=response.status;error.unknownOutcome=body.unknownOutcome===true;if(typeof body.code==='string'&&/^[a-z_]{1,64}$/.test(body.code))error.code=body.code;throw error;}
