function currentPresence(){return formatPresence({...state,controller:eventConnected?state.controller:{...state.controller,status:'offline',cached:true},callActiveNow:!!pc&&callConnected&&pc.connectionState==='connected'&&callChannel?.readyState==='open'},language());}
function chatSearchLabel(){return language()==='en'?'Search chat':'搜索聊天';}
function unreadAssistant(message){return message?.role==='assistant'&&message.kind!=='call'&&message.status==='completed'&&message.read!==true&&!message.receipt?.readAt&&!message.readAt&&!message.visibleAt;}
