function unreadLabel(count){return language()==='en'?count+' unread '+(count===1?'message':'messages'):count+' 条未读消息';}
function renderAssistantReadState(message){return message.status==='completed'?`<span class="message-read-state" data-read-state="${unreadAssistant(message)?'unread':'read'}">${unreadAssistant(message)?language()==='en'?'Unread':'未读':t('read')}</span>`:'';}
function renderUnreadControl(){const count=unreadMessages().length;return count?`<button type="button" class="unread-jump" data-first-unread title="${language()==='en'?'Jump to first unread message':'跳到第一条未读消息'}" aria-label="${esc(unreadLabel(count))}">${ico('arrow-down')}<span>${esc(unreadLabel(count))}</span></button>`:'';}
function revealMessage(){page='chat';chatMode='text';if(speechBlocked())callMini=true;render();}
function updatePresence(){if(!state)return;const presence=currentPresence(),label=document.querySelector('[data-presence-label]'),detail=document.querySelector('[data-presence-detail]'),dot=document.querySelector('[data-presence-dot]');if(label)label.textContent=presence.label;if(detail){detail.textContent=presence.detail?' · '+presence.detail:'';detail.hidden=!presence.detail;}if(dot)dot.className='status-dot '+(presence.active?'working':presence.online?'online':'offline');const status=document.querySelector('.presence-status');if(status)status.title=presence.title;}
