function renderDraftAttachment(file){return `<span class="${String(file.type||'').startsWith('audio/')?'draft-audio':''}" data-id="${esc(file.id)}">${ico(String(file.type||'').startsWith('audio/')?'mic':'paperclip')}<span>${esc(file.name)}</span>${String(file.type||'').startsWith('audio/')?`<audio controls preload="metadata" src="${esc(fileURL(file))}" aria-label="${esc(file.name)}"></audio>`:''}<button type="button" data-remove="${esc(file.id)}" aria-label="${t('close')}">×</button></span>`;}
