function clearTelegramPairing(){clearTimeout(telegramPairTimer);telegramPairTimer=null;telegramPairing=null;}
async function loadTelegram(){
 if(telegramLoading||!telegramOnline())return;telegramLoading=true;telegramError='';render();try{setTelegramStatus(await api('/telegram'));}catch(error){telegramError=error.message||String(error);}finally{telegramLoading=false;render();}
}
async function updateTelegram(kind,body){
 if(!telegramOnline())throw Error(t('telegramOffline'));if(pendingActions.has('telegram'))return;pendingActions.add('telegram');telegramError='';render();
 try{
  if(kind==='config'){setTelegramStatus(await post('/telegram/config',body));clearTelegramPairing();toast(t('telegramSaved'));}
  if(kind==='pair'){const result=await post('/telegram/pair');clearTelegramPairing();telegramPairing=result;telegramPairTimer=setTimeout(()=>{telegramPairing=null;telegramPairTimer=null;if(page==='settings')render();},Math.max(0,result.expiresAt-Date.now()));}
  if(kind==='disconnect'){setTelegramStatus(await post('/telegram/disconnect',body));clearTelegramPairing();const secret=document.querySelector('#telegram-token');if(secret)secret.value='';toast(t(body.clearToken?'telegramRemoved':'telegramUnbound'));}
 }catch(error){telegramError=error.message||String(error);throw error;}finally{pendingActions.delete('telegram');render();}
}
